mapper.select:
select member_idx, member_id, member_name, member_phone, member_gender, member_email, member_join_date,
member_level, member_status
from tb_member where member_idx=#{memberIdx}

select room_idx, room_name, room_size, room_basic_person, room_max_person, room_price_weekdays, room_price_weekend, room_price_shoulder_weekdays, room_price_shoulder_weekend, room_price_peak_weekdays, room_price_peak_weekend, room_service
from tb_room
where room_idx=#{roomIdx}
